/**
 * Add sheet.
 *
 * @param Worksheet $worksheet The worksheet to add
 * @param null|int $sheetIndex Index where sheet should go (0,1,..., or null for last)
 */
public function addSheet(Worksheet $worksheet, ?int $sheetIndex = null): Worksheet
{
    if ($this->sheetNameExists($worksheet->getTitle())) {
        throw new Exception(
            "Workbook already contains a worksheet named '{$worksheet->getTitle()}'. Rename this worksheet first."
        );
    }

    if ($sheetIndex === null) {
        if ($this->activeSheetIndex < 0) {
            $this->activeSheetIndex = 0;
        }
        $this->workSheetCollection[] = $worksheet;
    } else {
        // Insert the sheet at the requested index
        array_splice(
            $this->workSheetCollection,
            $sheetIndex,
            0,
            [$worksheet]
        );

        // Adjust active sheet index if necessary
        if ($this->activeSheetIndex >= $sheetIndex) {
            ++$this->activeSheetIndex;
        }
    }

    if ($worksheet->getParent() === null) {
        $worksheet->rebindParent($this);
    }

    return $worksheet;
}

/**
 * Calculate column widths of a worksheet from autosize flags, cell contents, and styles.
 */
public function calculateColumnWidths(Worksheet $worksheet): Worksheet
{
    $autoSizes = [];
    foreach ($worksheet->getColumnDimensions() as $colDimension) {
        if ($colDimension->getAutoSize()) {
            $autoSizes[$colDimension->getColumnIndex()] = -1;
        }
    }

    if (!empty($autoSizes)) {
        $holdActivePane = $worksheet->getActivePane();
        $autoFilterIndentRanges = (new AutoFit($worksheet))->getAutoFilterIndentRanges();

        foreach ($worksheet->getCoordinates(false) as $coordinate) {
            $cell = $worksheet->cellExists($coordinate) ? $worksheet->getCell($coordinate) : null;
            $columnId = Coordinate::coordinateFromString($coordinate)[0];

            if ($cell !== null && isset($autoSizes[$columnId])) {
                $isMerged = $cell->isInMergeRange();
                $isMergedButProceed = false;

                if ($isMerged && $cell->isMergeRangeValueCell()) {
                    $range = (string) $cell->getMergeRange();
                    $rangeBoundaries = Coordinate::rangeDimension($range);
                    if ($rangeBoundaries[0] === 1) {
                        $isMergedButProceed = true;
                    }
                }

                if (!$isMerged || $isMergedButProceed) {
                    $filterAdjustment = false;
                    if (!empty($autoFilterIndentRanges)) {
                        foreach ($autoFilterIndentRanges as $autoFilterFirstRowRange) {
                            if ($cell->isInRange($autoFilterFirstRowRange)) {
                                $filterAdjustment = true;

                                break;
                            }
                        }
                    }

                    $style = $cell->getStyle();
                    $alignment = $style->getAlignment();
                    $indentAdjustment = $alignment->getIndent();
                    $indentAdjustment += (int) ($alignment->getHorizontal() === Alignment::HORIZONTAL_CENTER);
                    $cellValue = NumberFormat::toFormattedString(
                        $cell->getCalculatedValueString(),
                        (string) $style->getNumberFormat()->getFormatCode(true)
                    );

                    if ($cellValue !== null && $cellValue !== '') {
                        $autoSizes[$columnId] = max(
                            $autoSizes[$columnId],
                            round(
                                SharedFont::calculateColumnWidth(
                                    $style->getFont(),
                                    $cellValue,
                                    (int) $alignment->getTextRotation(),
                                    $this->getDefaultStyle()->getFont(),
                                    $filterAdjustment,
                                    $indentAdjustment
                                ),
                                3
                            )
                        );
                    }
                }
            }
        }

        foreach ($autoSizes as $columnIndex => $width) {
            if ($width == -1) {
                $width = $worksheet->getDefaultColumnDimension()->getWidth();
            }
            $worksheet->getColumnDimension($columnIndex)->setWidth($width);
        }
        $worksheet->setActivePane($holdActivePane);
    }

    return $worksheet;
}

/**
 * Remove sheet by index.
 *
 * @param int $sheetIndex Index position of the worksheet to remove
 */
public function removeSheetByIndex(int $sheetIndex): void
{
    $numSheets = count($this->workSheetCollection);
    if ($sheetIndex > $numSheets - 1) {
        throw new Exception(
            "You tried to remove a sheet by the out of bounds index: {$sheetIndex}. The actual number of sheets is {$numSheets}."
        );
    }
    array_splice($this->workSheetCollection, $sheetIndex, 1);

    // Adjust active sheet index if necessary
    if (
        ($this->activeSheetIndex >= $sheetIndex)
        && ($this->activeSheetIndex > 0 || $numSheets <= 1)
    ) {
        --$this->activeSheetIndex;
    }
}

/**
 * Get sheet by index.
 *
 * @param int $sheetIndex Sheet index
 */
public function getSheet(int $sheetIndex): Worksheet
{
    if (!isset($this->workSheetCollection[$sheetIndex])) {
        $numSheets = $this->getSheetCount();

        throw new Exception(
            "Your requested sheet index: {$sheetIndex} is out of bounds. The actual number of sheets is {$numSheets}."
        );
    }

    return $this->workSheetCollection[$sheetIndex];
}

/**
 * Get all sheets.
 *
 * @return Worksheet[]
 */
public function getAllSheets(): array
{
    return $this->workSheetCollection;
}

/**
 * Get sheet by name.
 *
 * @param string $worksheetName Sheet name
 */
public function getSheetByName(string $worksheetName): ?Worksheet
{
